import{_ as o,o as a,c as l,ae as t}from"./chunks/framework.DQC_QtFV.js";const u=JSON.parse('{"title":"工作区","description":"","frontmatter":{},"headers":[],"relativePath":"guide/console/workspace.md","filePath":"guide/console/workspace.md","lastUpdated":1793162416000}'),i={name:"guide/console/workspace.md"};function c(r,e,d,s,n,p){return a(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="工作区" tabindex="-1">工作区 <a class="header-anchor" href="#工作区" aria-label="Permalink to &quot;工作区&quot;">​</a></h1><p>工作区页三张卡片：环境变量、Skills、MCP 服务器。前两个是沙箱的命令能碰到的东西， 第三个是模型能调用的外部函数。</p><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h2><p>沙箱里每条命令都会带上这些变量。一条变量有名字和 明文 / 保密 两种； 保密值只写不读，任何输出里的保密值都会被替换成 <code>[已隐藏:名字]</code>， 带着保密值的消息在发出去之前就被代码拦下，不问 Jev。</p><ul><li>名字必须是 shell 变量名（字母开头，64 字符以内）。</li><li>沙箱自己的固定项不能被覆盖：<code>PATH</code>、<code>HOME</code>、代理设置、<code>LD_PRELOAD</code> 等—— 它们是宿主该定的，不是模型该定的，页面会说明是哪一条。</li><li>保密值至少 8 个字符，这样脱敏才匹配不到普通文本。</li></ul><p>改动对下一条命令生效，不需要重建任何容器。</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p>技能装在 <code>/workspace/skills</code> 里，<strong>模型可以自己读、自己改、自己装</strong>； 这一卡片管的是&quot;源&quot;：一个地址，安装程序按周期把它拉下来更新。</p><ul><li>地址可以是 GitHub 简写（<code>owner/repo</code>）或 <code>https://</code> 的 git 地址； SSH 地址、本地路径、指向单个文件的地址都会被拒绝并说明原因 （代理只隧道 443，沙箱也看不到工作区以外的东西）。</li><li>周期 1 到 365 天，默认 7。</li><li>每行显示装到哪个 commit、上次更新于何时、正常 / 失败；失败的带原因， 同时出现在 概览 的 待处理 里。立即更新 手动跑一次，移除 只去掉这个源， 它装好的技能留在工作区。</li></ul><h2 id="mcp-服务器" tabindex="-1">MCP 服务器 <a class="header-anchor" href="#mcp-服务器" aria-label="Permalink to &quot;MCP 服务器&quot;">​</a></h2><p>模型只能在 <code>code_exec</code> 里用 <code>tools[&quot;服务器.函数&quot;](args)</code> 调用 MCP 服务器； 函数名先让模型用 <code>tool_search</code> 查。系统提示里每个服务器占一行，随窗口冻结， 所以停用一个服务器或一个函数不会改动这一行——调用会被拒绝并说明原因。</p><ul><li>添加 / 编辑 / 停用 / 删除，一行一个服务器：状态（已连接 / 需要授权 / 错误）、 函数个数、其中停用几个、传输方式、授权状态。</li><li>行展开就是这个服务器提供的函数：名字、描述、参数、一个开关。</li><li>传输方式三种：Streamable HTTP、SSE、stdio（stdio 的在沙箱里跑，出网只走代理）。</li><li>认证三种：无、请求头（头的值填一个 <a href="#环境变量">环境变量</a> 的名字，连接时读取， 不落库、不返回）、OAuth。</li><li>服务器名是小写标识符，脚本里写起来不用加引号；地址、命令、client id 这些 技术值只接受英文字母、数字和标点，表单在输入框下面写清规则，不达标存不下去。</li></ul><p>OAuth 的授权流程单独一页：<a href="./../mcp.html">MCP 客户端</a>。</p>',13)])])}const _=o(i,[["render",c]]);export{u as __pageData,_ as default};
